import pyAether as pyScript

# 获取单元对象
lib_name = pyScript.emyString("TECHLIB")
cell_name = pyScript.emyString("CAPPARAVSS")
dm_cell_obj = pyScript.dmGetObj(lib_name, cell_name)

# 获取单元对象类型
cell_type = pyScript.dmGetObjType(dm_cell_obj)
print(f"Cell type: {cell_type}")  # 输出: cellType
```

### 示例3：获取视图对象类型
